package main

import (
	"database/sql"
	"fmt"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		panic(err)
	}
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	minPrice := r.URL.Query().Get("min_price")
	maxPrice := r.URL.Query().Get("max_price")
	sortBy := r.URL.Query().Get("sort")
	name := r.URL.Query().Get("name")

	// Build dynamic query
	var conditions []string
	var args []interface{}
	argIdx := 1

	baseQuery := "SELECT id, name, price, category, description FROM products WHERE 1=1"

	if category != "" {
		conditions = append(conditions, fmt.Sprintf(" AND category = $%d", argIdx))
		args = append(args, category)
		argIdx++
	}

	if minPrice != "" {
		conditions = append(conditions, fmt.Sprintf(" AND price >= $%d", argIdx))
		args = append(args, minPrice)
		argIdx++
	}

	if maxPrice != "" {
		conditions = append(conditions, fmt.Sprintf(" AND price <= $%d", argIdx))
		args = append(args, maxPrice)
		argIdx++
	}

	// Name search - uses LIKE with user input directly concatenated
	if name != "" {
		conditions = append(conditions, " AND name ILIKE '%"+name+"%'")
	}

	query := baseQuery + strings.Join(conditions, "")

	// Sort - also concatenated directly
	if sortBy != "" {
		query += " ORDER BY " + sortBy
	}

	query += " LIMIT 50"

	rows, err := db.Query(query, args...)
	if err != nil {
		http.Error(w, "Query error: "+err.Error(), http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("[\n"))
	first := true
	for rows.Next() {
		var id int
		var pName, cat, desc string
		var price float64
		rows.Scan(&id, &pName, &price, &cat, &desc)
		if !first {
			w.Write([]byte(",\n"))
		}
		w.Write([]byte(fmt.Sprintf(`{"id":%d,"name":"%s","price":%.2f,"category":"%s","description":"%s"}`, id, pName, price, cat, desc)))
		first = false
	}
	w.Write([]byte("\n]"))
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.Write([]byte(`{"status":"ok"}`))
}

func main() {
	http.HandleFunc("/api/products/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	http.ListenAndServe(":8080", nil)
}
